import unittest
from merge import deep_merge

class RegressionTests(unittest.TestCase):
    def test_top_level_replace(self):
        left = {'a': 1, 'b': 2}
        right = {'b': 3, 'c': 4}
        self.assertEqual(deep_merge(left, right), {'a': 1, 'b': 3, 'c': 4})
        self.assertEqual(left, {'a': 1, 'b': 2})

    def test_empty_right(self):
        left = {'a': 1}
        self.assertEqual(deep_merge(left, {}), {'a': 1})
        self.assertIsNot(deep_merge(left, {}), left)

    def test_non_dict_overwrites_dict(self):
        self.assertEqual(deep_merge({'a': {'x': 1}}, {'a': 9}), {'a': 9})

